  ('6fb9c29e-38c4-5f0f-a43a-02ef6a50d004', '22222222-2222-2222-2222-22222222221c', 'short', '𝑥1 + 𝑎, 𝑥2 + 𝑎, ⋯, 𝑥𝑛+ 𝑎的方差为𝑆2.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 18, true, 35, null),
  ('04b291e9-084d-54cb-8d52-4a4c1038b66e', '22222222-2222-2222-2222-22222222221c', 'short', '𝑚𝑥1, 𝑚𝑥2, ⋯, 𝑚𝑥𝑛的方差为𝑚2𝑆2.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 18, true, 36, null),
  ('4a50563f-e553-5b64-9215-b92a622c7034', '22222222-2222-2222-2222-22222222221c', 'short', '𝑚𝑥1 + 𝑎, 𝑚𝑥2 + 𝑎, ⋯, 𝑚𝑥𝑛+ 𝑎的方差为𝑚2𝑆2. 四、标准差 标准差记为𝑆. 题型1：考查方差的计算', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 18, true, 37, null),
  ('fc3bb492-7d00-5689-a3a8-9453bfcd5df5', '22222222-2222-2222-2222-22222222221c', 'mcq', '已知一组数据：−2, −1,0, 𝑥, 1的平均数是0，则方差𝑆2=( ).', '[{"key": "A", "text": "0"}, {"key": "B", "text": "1"}, {"key": "C", "text": "2"}, {"key": "D", "text": "√2"}, {"key": "E", "text": "3"}]'::jsonb, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 18, true, 38, null),
  ('bfd1023e-6dc0-5cee-bc4e-f904f17371e4', '22222222-2222-2222-2222-22222222221c', 'mcq', '某人5 次上班途中所花的时间（单位：分钟）分别为𝑥, 𝑦, 10,11,9.已知 这组数据的平均数为10，方差为2，则|𝑥−𝑦|的值为( ).', '[{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}, {"key": "E", "text": "5"}]'::jsonb, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 19, true, 39, null),
  ('12ed4fb1-c4f0-56c0-ae5a-0472332ce519', '22222222-2222-2222-2222-22222222221c', 'mcq', '某工厂生产零件，有新旧两条生产线。 质检部从从两条生产线各随机 抽取 5 个零件，测量其直径(单位：mm)，数据如下： 甲生产线 21 22 23 24 25 乙生产线 100 101 102 103 104 已知两条生产线的设计标准不同（甲线生产小型零件，乙线生产大型零 件），但工艺稳定性相当。设两组数据的方差分别为𝑆1 2, 𝑆2 2，则下列正确 的是( ).', '[{"key": "A", "text": "𝑆1 2 > 𝑆2 2"}, {"key": "B", "text": "𝑆1 2 < 𝑆2 2"}, {"key": "C", "text": "𝑆1 2 = 𝑆2 2"}, {"key": "D", "text": "𝑆1 2 ≠𝑆2 2"}, {"key": "E", "text": "无法确定𝑆1 2, 𝑆2 2的大小关系 你的坚持，终将美好！ 9 你的坚持，终将美好！ 10 考点3：数据的图表表示 一、直方图"}]'::jsonb, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 19, true, 40, null),
  ('77cb8af4-de88-5b0d-a135-0d3c83bb8139', '22222222-2222-2222-2222-22222222221c', 'short', '定义 把数据分为若干个小组，每组的组距保持一致，并在直角坐标系的横轴 上标出每组的位置 （以组距作为底），计算每组所包含的数据个数(频数)， 以该组的“频率/组距”为高作矩形，这样得出若干个矩形构成的图叫做 直方图.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 41, null),
  ('36a5854a-cc24-5eb1-917d-8b003be2e2d0', '22222222-2222-2222-2222-22222222221c', 'short', '公式', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 42, null),
  ('d36c833f-3b23-5790-af5b-5bc646b57f81', '22222222-2222-2222-2222-22222222221c', 'short', '组距的确定：一般是人为确定，不能太大也不能太小.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 43, null),
  ('ed714f65-af5e-5f11-9a4a-dd79a6479a74', '22222222-2222-2222-2222-22222222221c', 'short', '组数的确定：组数= 极差 组距.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 44, null),
  ('39f2cab5-613e-576d-8bdb-0429fb554f63', '22222222-2222-2222-2222-22222222221c', 'short', '每组频率的确定：频率= 频数 数据容量.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 45, null),
  ('d1420680-52de-57da-8a43-16badee3137c', '22222222-2222-2222-2222-22222222221c', 'short', '每组所确定的矩形的面积= 组距× 频率 组距= 频率.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 46, null),
  ('81d99a69-c9b3-5b6a-bfef-6aa2ff47578d', '22222222-2222-2222-2222-22222222221c', 'short', '频率直方图下的矩形总面积等于1.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 47, null),
  ('1d85d88f-cc6d-5b6a-bc62-6f2e5369c48d', '22222222-2222-2222-2222-22222222221c', 'short', '频数=总人数× 频率.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 48, null),
  ('76eb02aa-fa79-5a44-ab13-0ce5a3b53c99', '22222222-2222-2222-2222-22222222221c', 'short', '分组时要遵循“不重不漏”的原则：“不重”是指某一个数据只能分 在其中的某一组，不能在其他组中出现； “不漏”是指组别能穷尽，， 即在所分的全部组别中每项数据都能分在其中的某一组，不能遗漏. 分组时采用左闭右开的区间表示：[ ). 例如，某数据分组时，其中的两组分别为[227,290)和[290,353)，这 样290 这个数据就只存在于第二个区间中了，避免290 同时属于两 个区间的情况发生. 你的坚持，终将美好！ 11 题型1：考查直方图', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 49, null),
  ('60d1c594-f066-58f2-94f0-6af6c1ff5751', '22222222-2222-2222-2222-22222222221c', 'mcq', '某学校组织学生参加英语测试，成绩的频率分布直方图如图，数据的分 组依次为[20, 40),[40,60),[60,80),[80,100).若低于60 分的人数是15 人， 则该班的学生人数是( ).', '[{"key": "A", "text": "45"}, {"key": "B", "text": "50"}, {"key": "C", "text": "55"}, {"key": "D", "text": "60"}, {"key": "E", "text": "70"}]'::jsonb, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 22, true, 50, null),
  ('70fc98e6-264b-59ac-882e-26fe3d7d8473', '22222222-2222-2222-2222-22222222221c', 'short', '定义 饼图是以圆形和扇形表示数据的统计图形，扇形的圆心角之比等于频数 之比，圆心角的大小直观地表示度量值的大小关系. 通过扇形的大小可 以反映各个部分占总体的百分比.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 23, true, 51, null),
  ('c5ab2ebe-ab20-52b8-8ae7-5fdddc003798', '22222222-2222-2222-2222-22222222221c', 'short', '公式 某部分所占的百分比等于对应扇形所占整个圆周的比例. 题型2：考查饼图', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 23, true, 52, null),
  ('1630d155-ce76-527c-b64f-595df93c2d72', '22222222-2222-2222-2222-22222222221c', 'mcq', '在一次捐款活动中，某班50 名同学每人拿出自己的零花钱，有捐5 元、 10 元、20 元的，还有捐50 元和100 元的，不同捐款数的人数比例如 图所示，则该班同学平均每人捐款( )元.', '[{"key": "A", "text": "30"}, {"key": "B", "text": "30.6"}, {"key": "C", "text": "31"}, {"key": "D", "text": "31.2"}, {"key": "E", "text": "32"}]'::jsonb, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 23, true, 53, null),
